def main():
    ap = argparse.ArgumentParser(description=__doc__,
                                  formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--output", default="FABLE_Pakistan_Production_Standardized.csv",
                     help="Path to write the file to (default: %(default)s)")
    args = ap.parse_args()

    data = base64.b64decode(_FILE_B64)
    with open(args.output, "wb") as f:
        f.write(data)

    print(f"Wrote {len(data):,} bytes to {args.output}")
    print("SHA256: " + __import__("hashlib").sha256(data).hexdigest())


if __name__ == "__main__":
    main()
